CREATE FUNCTION public.treasure_travel(p_steps jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE step jsonb; result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF jsonb_typeof(p_steps) IS DISTINCT FROM 'array' OR jsonb_array_length(p_steps)>32 THEN RAISE EXCEPTION 'Invalid path'; END IF; FOR step IN SELECT value FROM jsonb_array_elements(p_steps) LOOP IF jsonb_typeof(step->'x') IS DISTINCT FROM 'number' OR jsonb_typeof(step->'y') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid step'; END IF; result:=public.treasure_action('move',(step->>'x')::int,(step->>'y')::int,NULL,NULL); END LOOP; IF result IS NULL THEN result:=public.treasure_action('status'); END IF; RETURN result; END $$; REVOKE ALL ON FUNCTION public.treasure_travel(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.treasure_travel(jsonb) TO authenticated;